local B64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={}
for i=1,64 do M[B64:sub(i,i)]=i-1 end
local function d(s)
    local o={}
    local i=1
    while i<=#s do
        local c1,c2,c3,c4=s:byte(i,i+3)
        if not c1 then break end
        local a=M[string.char(c1)] or 0
        local b=c2 and (M[string.char(c2)] or 0) or 0
        local c=c3 and (M[string.char(c3)] or 0) or 0
        local e=c4 and (M[string.char(c4)] or 0) or 0
        local n=a*262144+b*4096+c*64+e
        o[#o+1]=string.char(math.floor(n/65536)%256)
        if c3 and string.char(c3)~="=" then o[#o+1]=string.char(math.floor(n/256)%256) end
        if c4 and string.char(c4)~="=" then o[#o+1]=string.char(n%256) end
        i=i+4
    end
    return table.concat(o)
end
