local raw=d(s)
local out={}
for i=1,#raw do
    out[i]=string.char(bit32.bxor(string.byte(raw,i), K, i%251))
end
local code=table.concat(out)
local fn,err=loadstring(code)
if not fn then
    local sg=game:GetService("StarterGui")
    pcall(function() sg:SetCore("SendNotification",{Title="Berlin",Text="解密失败："..tostring(err),Duration=6}) end)
    return
end
return fn()
